import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"高通滤波器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/high_pass/index.md","filePath":"v0.1.0-alpha/modules/high_pass/index.md"}'),c={name:"v0.1.0-alpha/modules/high_pass/index.md"};function r(n,t,i,l,h,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="高通滤波器" tabindex="-1">高通滤波器 <a class="header-anchor" href="#高通滤波器" aria-label="Permalink to &quot;高通滤波器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>high_pass</code> · 模块定义版本：4</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>衰减直流和较低频率，保留较高频率。它适合观察去除慢变化分量后的波形，以及比较低通与高通的选频方向。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>混合信号.out → 高通滤波器.in</code>。将同一混合信号另分支给低通，分别选择两路输出观察；这两个滤波器各自生成自己的结果。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>截止频率和过渡带使用 Hz，但必须以正确的输入采样率为基础。高通不会保留超过 Nyquist 频率的连续信号；这些成分在采样时可能已混叠。</p><p>窗与过渡带共同决定抽头设计。抽取时尤其要检查所保留的高频是否仍落在新输出率允许的范围内；高通本身不能替代降采样前需要的抗混叠低通。</p><p><code>window_param</code> 随设计窗解释：Kaiser 使用 β（≥ 0）；Exponential 使用半窗长度上的衰减 d（dB，≥ 0）；Gaussian 使用 σ（&gt; 0）；Tukey 使用 α（0 ≤ α ≤ 1）。这个参数只对相应四种窗有意义，其他窗不靠它改变。切换窗后按新的含义检查数值，尤其不能给 Tukey 沿用超出 0 到 1 的旧值。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 5e-324 至 1000000；须等于上游实际采样率，可低于 1 Hz。插值滤波按输出采样率设计抽头。</td><td>重新准备</td></tr><tr><td>截止频率 (Hz)<br><code>cutoff_hz</code></td><td><code>512</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>过渡带宽 (Hz)<br><code>transition_hz</code></td><td><code>128</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>通带增益<br><code>gain</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>设计窗函数<br><code>window</code></td><td><code>hamming</code></td><td>Hamming (<code>hamming</code>)；Hann (<code>hann</code>)；Blackman (<code>blackman</code>)；Rectangular (<code>rectangular</code>)；Kaiser (<code>kaiser</code>)；Blackman-Harris (<code>blackman_harris</code>)；Bartlett (<code>bartlett</code>)；Flat top (<code>flattop</code>)；Nuttall (<code>nuttall</code>)；Nuttall CFD (<code>nuttall_cfd</code>)；Welch (<code>welch</code>)；Parzen (<code>parzen</code>)；Exponential (<code>exponential</code>)；Riemann (<code>riemann</code>)；Gaussian (<code>gaussian</code>)；Tukey (<code>tukey</code>)</td><td>可在线应用</td></tr><tr><td>窗参数<br><code>window_param</code></td><td><code>6.76</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>抽取倍数<br><code>decimation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>插值倍数<br><code>interpolation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain</code>、<code>transition_hz</code>、<code>window</code>、<code>window_param</code>、<code>cutoff_hz</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线设计修改按完整设计组提交，成功与否看真实回执；抽头变长超出容量时需要重新准备。速率和结构变化同样要重新准备，旧图表样本不会被新设计重新计算。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><p>实数处理示例从同一个加法器分出高通支路。预期 768 Hz 分量保留而 64 Hz 分量明显减弱；波形看起来振荡更快。使用频谱读数区分选频结果和自动纵轴造成的视觉变化。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>输出均值接近零正常吗？</strong> 高通会衰减直流，先观察稳定段；起始边缘仍可能出现过渡响应。</p><p><strong>低频没有完全消失？</strong> FIR 的抑制有限，且截止附近有过渡区；检查实际频率与频带位置。</p>',29)])])}const m=d(c,[["render",r]]);export{u as __pageData,m as default};
